  const labelY=part.type==='microcontroller'?part.y+88:part.type==='plc'||part.type==='io-module'?part.y+66:part.y+34;
  const threePin=['npn-transistor','pnp-transistor','nmos','pmos','igbt','scr','triac','n-channel-jfet','p-channel-jfet','darlington-transistor','op-amp','comparator','logic-gate-and','logic-gate-or','logic-gate-not','logic-gate-xor'].includes(part.type);
