  const fitView=()=>{const points=[...parts.flatMap(part=>[{x:part.x-50,y:part.y-45},{x:part.x+50,y:part.y+55}]),...wires.flatMap(wire=>[{x:wire.x1,y:wire.y1},{x:wire.x2,y:wire.y2}])];if(!points.length){setZoom(100);canvasWrapRef.current?.scrollTo({left:0,top:0});setStatus('View reset to drawing origin');return;}const left=Math.max(0,Math.min(...points.map(point=>point.x))-40),top=Math.max(0,Math.min(...points.map(point=>point.y))-40),right=Math.max(...points.map(point=>point.x))+40,bottom=Math.max(...points.map(point=>point.y))+40;const fitScale=Math.min((viewportSize.width-60)/Math.max(1,right-left),(viewportSize.height-60)/Math.max(1,bottom-top),2.5);const nextZoom=Math.max(25,Math.min(250,Math.floor(fitScale*10)*10)),viewport=canvasWrapRef.current;setZoom(nextZoom);if(viewport)requestAnimationFrame(()=>viewport.scrollTo({left:left*nextZoom/100,top:top*nextZoom/100}));setStatus('View fitted to drawing contents')};
