  const exportDrawingSheetSvg=()=>{if(!svgRef.current){setStatus('Drawing canvas is not ready');return;}const clone=svgRef.current.cloneNode(true) as SVGSVGElement;clone.querySelectorAll('.canvas-bg').forEach(n=>n.remove());const drawingPoints=[...parts.map(part=>({x:part.x,y:part.y})),...wires.flatMap(wire=>[{x:wire.x1,y:wire.y1},{x:wire.x2,y:wire.y2}])];let viewBox='0 0 1100 778';if(drawingPoints.length){const left=Math.min(0,...drawingPoints.map(point=>point.x-100)),top=Math.min(0,...drawingPoints.map(point=>point.y-100)),right=Math.max(1100,...drawingPoints.map(point=>point.x+100)),bottom=Math.max(778,...drawingPoints.map(point=>point.y+100));viewBox=[left,top,right-left,bottom-top].join(' ')}const source=new XMLSerializer().serializeToString(clone);const inner=source.slice(source.indexOf('>')+1,source.lastIndexOf('</svg>'));const xml=(v:unknown)=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');const label=(x:number,y:number,k:string,v:unknown)=>'<text x="'+x+'" y="'+y+'" font-family="Arial,sans-serif" font-size="11" fill="#4b5c66">'+xml(k.toUpperCase())+'</text><text x="'+x+'" y="'+(y+20)+'" font-family="Arial,sans-serif" font-size="16" fill="#101820">'+xml(v||'—')+'</text>';const date=new Date().toISOString().slice(0,10);const output='<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1131" viewBox="0 0 1600 1131"><rect width="1600" height="1131" fill="#fff"/><rect x="25" y="25" width="1550" height="1081" fill="none" stroke="#101820" stroke-width="2"/><rect x="40" y="40" width="1520" height="815" fill="#0d171e"/><svg x="40" y="40" width="1520" height="815" viewBox="'+xml(viewBox)+'" preserveAspectRatio="xMidYMid meet">'+inner+'</svg><rect x="40" y="870" width="1520" height="230" fill="#fff" stroke="#101820" stroke-width="1.5"/><path d="M40 930H1560 M40 990H1560 M40 1050H1560 M540 930V1100 M950 930V1100 M1250 930V1100" stroke="#101820" stroke-width="1" fill="none"/>'+label(55,892,'Project / drawing title',projectName+' — '+sheet)+label(55,950,'Project number',metadata.projectNumber)+label(555,950,'Client',metadata.client)+label(965,950,'Engineer / designer',metadata.engineer)+label(1265,950,'Revision',metadata.revision)+label(55,1010,'Applicable standard',metadata.standard)+label(555,1010,'Sheet',sheet)+label(965,1010,'Issue date',date)+label(1265,1010,'Units',units)+label(55,1070,'Issue status','PRELIMINARY — NOT FOR CONSTRUCTION · QA / PROFESSIONAL APPROVAL REQUIRED')+'</svg>';downloadText('voltpro-drawing-sheet-'+String(metadata.projectNumber||'VP').replace(/[^a-z0-9_-]/gi,'_')+'.svg',output,'image/svg+xml');setStatus('Drawing sheet SVG exported with project title block; it is not certified or approved for construction.')};
  const deleteSelected=()=>{if(!selected)return;remember();setParts(p=>p.filter(x=>x.id!==selected));setWires(w=>w.filter(x=>x.id!==selected));setSelected(null);setStatus('Item deleted');};
  const runDiagnostics=()=>{setRightOpen(true);setRightPanel('results');const sheetData=stashSheet();const issues:Diagnostic[]=[];const refs=new Map<string,string[]>();for(const p of parts){const key=p.ref.trim().toLowerCase();if(!key){issues.push({severity:'error',code:'EMPTY_REF',message:p.type+' has an empty device reference'});continue;}refs.set(key,[...(refs.get(key)||[]),p.id]);}for(const [ref,ids] of refs)if(ids.length>1)issues.push({severity:'error',code:'DUPLICATE_REF',message:'Duplicate device reference '+ref+' ('+ids.length+' components)'});if(parts.length&&!parts.some(p=>p.type.includes('ground')))issues.push({severity:'error',code:'MISSING_GROUND',message:'No explicit ground/reference symbol is present'});const segments=wires.flatMap(w=>[[{x:w.x1,y:w.y1},{x:w.x2,y:w.y1}],[{x:w.x2,y:w.y1},{x:w.x2,y:w.y2}]]);const onSegment=(p:{x:number;y:number},a:{x:number;y:number},b:{x:number;y:number})=>Math.abs((b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x))<1&&p.x>=Math.min(a.x,b.x)-1&&p.x<=Math.max(a.x,b.x)+1&&p.y>=Math.min(a.y,b.y)-1&&p.y<=Math.max(a.y,b.y)+1;const excluded=['text-note','net-label','wire-label','wire-crossing','junction','cable','shield','ferrule','busbar'];for(const p of parts){const model=componentById(p.type)?.model;if(model==='unsupported'&&!excluded.includes(p.type))issues.push({severity:'warning',code:'NO_SIM_MODEL',message:p.ref+' ('+p.type+') has no validated DC simulation model'});if(!excluded.includes(p.type)&&wires.length){const pins=connectablePins(p);const floating=pins.filter(pin=>!segments.some(([a,b])=>onSegment(pin,a,b)));if(floating.length)issues.push({severity:'warning',code:'FLOATING_PIN',message:p.ref+' has '+floating.length+' unconnected pin(s) by current wire geometry'});}}for(const w of wires)if(Math.hypot(w.x2-w.x1,w.y2-w.y1)<1)issues.push({severity:'warning',code:'ZERO_LENGTH_WIRE',message:'Wire '+w.id+' has a zero-length endpoint span'});if(!issues.length)issues.push({severity:'info',code:'NO_BASIC_ISSUES',message:'No duplicate references or obvious basic connectivity issues detected. This is not a standards or safety check.'});setDiagnostics(issues);setTab('Diagnostics');setStatus('Basic diagnostics completed: '+issues.length+' finding(s)');return issues;};
