  const exportDwg=async()=>{const endpoint=API_BASE?API_BASE+'/api/export/dwg':import.meta.env.DEV?'/api/export/dwg':'';if(!endpoint){setStatus('Native DWG export needs VITE_API_BASE_URL pointing to a VoltPro API host with GNU LibreDWG dxf2dwg installed. DXF export remains available.');return;}try{const response=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({dxf:exportDrawingDxf(documentData())})});if(!response.ok){let message='Native DWG conversion failed';try{message=(await response.json()).error||message}catch(e){}throw new Error(message)}const blob=await response.blob();if(blob.size<64)throw new Error('DWG converter returned an empty file');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='voltpro-schematic-r2000.dwg';a.click();URL.revokeObjectURL(url);setStatus('LibreDWG generated a DWG file. Verify it opens correctly in your target CAD software; conversion is experimental.')}catch(error){setStatus(error instanceof Error?error.message:'Native DWG export failed')}};
